#!/bin/bash
# Final renders for the two 2026-11-14 long-forms, ONE AT A TIME (running both at once crashed Chrome). Do not edit this file while it runs.
# Resumable: any chunk already on disk is skipped, so just re-run this script after a crash or a reboot.
# Usage:  bash scripts/long-form/render_pending.sh money2   # What If Money Disappeared (v4, rendered)
#         bash scripts/long-form/render_pending.sh boss2    # POV boss video (v3)
set -u
ROOT=/Users/yellow/Projects/MrYellowScarf
CHROME="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
cd "$ROOT/remotion" || exit 1

START=$(date +%s); DONE_N=0
fmt () { printf '%02d:%02d:%02d' $(($1/3600)) $(($1%3600/60)) $(($1%60)); }

render_chunk () { # comp entry out a b   (uses CUR / TOTAL set by the caller for the progress line)
  local comp=$1 entry=$2 out=$3 a=$4 b=$5
  [ -s "$out" ] && { echo "[chunk ${CUR:-?}/${TOTAL:-?}] already done, skipping $(basename $out)"; return 0; }
  local t0=$(date +%s)
  echo ""; echo "=== chunk ${CUR:-?}/${TOTAL:-?}  frames $a-$b  started $(date +%H:%M:%S) ==="
  for try in 1 2 3; do
    npx remotion render "$entry" "$comp" "$out" --frames=$a-$b --muted --concurrency=2 --gl=angle \
      --browser-executable="$CHROME" --log=warn && [ -s "$out" ] && {
      local now=$(date +%s); DONE_N=$((DONE_N+1))
      local per=$(( (now-t0) )) left=$(( ${TOTAL:-1} - ${CUR:-1} ))
      echo "=== chunk ${CUR:-?}/${TOTAL:-?} DONE in $(fmt $per) | total elapsed $(fmt $((now-START))) | about $(fmt $((per*left))) left (done by ~$(date -v+$((per*left))S +%H:%M)) ==="
      return 0; }
    rm -f "$out"; echo "retry $try for $out"
  done
  echo "FAILED $out"; return 1
}

finish () { # dir name  (concat parts -> raw60, mux audio -> final)
  local d=$1 name=$2
  local list=$d/output/parts.txt
  : > "$list"
  for f in "${@:3}"; do echo "file '$f'" >> "$list"; done
  ffmpeg -y -loglevel error -f concat -safe 0 -i "$list" -c copy "$d/output/raw60.mp4" || return 1
  ffmpeg -y -loglevel error -i "$d/output/raw60.mp4" -i "$d/audio/mix.wav" -c:v copy -c:a aac -b:a 192k -shortest "$d/output/$name.mp4" || return 1
  echo "DONE: $d/output/$name.mp4"
}

case "${1:-}" in
  money2)
    # money video REDO v4 (painted look, Joe's exact script): composition MnyLF60, 23887 frames at 60 fps in 8 chunks of 2986
    D=$ROOT/videos/long-form/what-if-money-disappeared; O=$D/output/chunks; mkdir -p $O
    P=()
    TOTAL=8; for i in 0 1 2 3 4 5 6 7; do
      CUR=$((i+1)); a=$((i*2986)); b=$(((i+1)*2986-1)); [ $i -eq 7 ] && b=23886
      render_chunk MnyLF60 src/mnylfIndex.ts $O/n$i.mp4 $a $b || exit 1
      P+=("$O/n$i.mp4")
    done
    finish $D what-if-money-disappeared "${P[@]}"
    ;;
  boss2)
    # boss video v3 (Joe's ChatGPT script, bright): composition Boss260, 23243 frames at 60 fps in 6 chunks of 3874
    D=$ROOT/videos/long-form/pov-boss-laughed-idea; O=$D/output/chunks; mkdir -p $O
    P=()
    TOTAL=6; for i in 0 1 2 3 4 5; do
      CUR=$((i+1)); a=$((i*3874)); b=$(((i+1)*3874-1)); [ $i -eq 5 ] && b=23242
      render_chunk Boss260 src/boss2Index.ts $O/b$i.mp4 $a $b || exit 1
      P+=("$O/b$i.mp4")
    done
    finish $D pov-boss-laughed-idea "${P[@]}"
    ;;
  island)
    # island POV video (Joe's script verbatim): composition Island60, 24551 frames at 60 fps in 6 chunks of 4092
    D=$ROOT/videos/long-form/pov-island-only-women; O=$D/output/chunks; mkdir -p $O
    P=()
    TOTAL=6; for i in 0 1 2 3 4 5; do
      CUR=$((i+1)); a=$((i*4092)); b=$(((i+1)*4092-1)); [ $i -eq 5 ] && b=24550
      render_chunk Island60 src/islandIndex.ts $O/s$i.mp4 $a $b || exit 1
      P+=("$O/s$i.mp4")
    done
    finish $D pov-island-only-women "${P[@]}"
    ;;
  islandshort)
    # funnel Short (9:16) for the island video: composition IslandShort60, 3054 frames at 60 fps, one chunk
    D=$ROOT/videos/short-form/island-funnel-short; O=$D/output/chunks; mkdir -p $O
    TOTAL=1; CUR=1
    render_chunk IslandShort60 src/islandShortIndex.ts $O/s0.mp4 0 3053 || exit 1
    finish $D island-funnel-short "$O/s0.mp4"
    ;;
  *) echo "usage: $0 money2|boss2|island|islandshort"; exit 1;;
esac
